import sys

def main():
    # Read input
    input = sys.stdin.read().split()
    N = int(input[0])
    M = int(input[1])
    A = int(input[2])
    B = int(input[3])
    bad_ranges = []
    idx = 4
    for _ in range(M):
        L = int(input[idx])
        R = int(input[idx + 1])
        bad_ranges.append((L, R))
        idx += 2

    # Create a list of bad squares
    bad_squares = set()
    for L, R in bad_ranges:
        for j in range(L, R + 1):
            bad_squares.add(j)

    # Dynamic programming
    dp = [False] * (N + 1)
    dp[1] = True
    for x in range(1, N + 1):
        if not dp[x]:
            continue
        for i in range(A, B + 1):
            next_x = x + i
            if next_x > N:
                continue
            if next_x not in bad_squares:
                dp[next_x] = True

    if dp[N]:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()

