from typing import List

class Solution:
    def sumOfGoodSubsequences(self, nums: List[int]) -> int:
        MOD = 10**9 + 7

        # Count the frequency of each number
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        # Sort the unique numbers
        sorted_nums = sorted(freq.keys())

        # dp[x] will store the sum of good subsequences ending with x
        dp = {}

        # Initialize dp with single elements
        for num in sorted_nums:
            dp[num] = freq[num] * num  # Each single element is a good subsequence

        # For each number, check if there is a number one less than it
        for num in sorted_nums:
            if num - 1 in dp:
                # Add the sum of subsequences ending with num-1 to dp[num]
                dp[num] = (dp[num] + dp[num - 1]) % MOD

        # Sum all values in dp to get the total sum of good subsequences
        return sum(dp.values()) % MOD

