class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        # Build adjacency list
        from collections import defaultdict
        import heapq

        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        # Sort edges by weight in descending order
        sorted_edges = []
        for u in graph:
            for v, w in graph[u]:
                sorted_edges.append((w, u, v))
        sorted_edges.sort(reverse=True)

        # Keep track of edges that are kept
        kept_edges = set()

        # Use a max-heap to keep track of edges that can be removed
        # We will use a min-heap with negative weights for max-heap behavior
        heap = []

        # Track the number of edges each node has
        edge_count = defaultdict(int)

        # Process edges in descending order of weight
        for w, u, v in sorted_edges:
            # If both nodes have less than k edges, keep the edge
            if edge_count[u] < k and edge_count[v] < k:
                kept_edges.add((u, v))
                kept_edges.add((v, u))
                edge_count[u] += 1
                edge_count[v] += 1
            else:
                # Add to heap if one of the nodes has reached k edges
                if edge_count[u] >= k:
                    heapq.heappush(heap, (-w, u, v))
                elif edge_count[v] >= k:
                    heapq.heappush(heap, (-w, v, u))

        # Now, check if we can replace some edges with higher weight edges
        # while maintaining the degree constraint
        while heap:
            neg_w, u, v = heapq.heappop(heap)
            w = -neg_w

            # Check if the edge is already kept
            if (u, v) in kept_edges or (v, u) in kept_edges:
                continue

            # Check if removing the edge would allow us to keep a higher weight edge
            # Find the current edges for u and v that have the lowest weights
            min_weight_u = float('inf')
            min_weight_v = float('inf')
            for nei, weight in graph[u]:
                if (u, nei) in kept_edges or (nei, u) in kept_edges:
                    if weight < min_weight_u:
                        min_weight_u = weight
            for nei, weight in graph[v]:
                if (v, nei) in kept_edges or (nei, v) in kept_edges:
                    if weight < min_weight_v:
                        min_weight_v = weight

            # If the current edge has higher weight than the minimum weight edges of u or v, replace it
            if w > min_weight_u or w > min_weight_v:
                # Remove the edge with lower weight
                if min_weight_u < min_weight_v:
                    # Find the edge with min_weight_u and remove it
                    for nei, weight in graph[u]:
                        if (u, nei) in kept_edges or (nei, u) in kept_edges:
                            if weight == min_weight_u:
                                kept_edges.remove((u, nei))
                                kept_edges.remove((nei, u))
                                edge_count[u] -= 1
                                edge_count[nei] -= 1
                                break
                else:
                    # Find the edge with min_weight_v and remove it
                    for nei, weight in graph[v]:
                        if (v, nei) in kept_edges or (nei, v) in kept_edges:
                            if weight == min_weight_v:
                                kept_edges.remove((v, nei))
                                kept_edges.remove((nei, v))
                                edge_count[v] -= 1
                                edge_count[nei] -= 1
                                break
                # Add the current edge
                kept_edges.add((u, v))
                kept_edges.add((v, u))
                edge_count[u] += 1
                edge_count[v] += 1

        # Calculate the sum of weights of the kept edges
        total_weight = 0
        for u in graph:
            for v, w in graph[u]:
                if (u, v) in kept_edges:
