import sys
from collections import deque

def solve():
    N = int(sys.stdin.readline())
    graph = []
    for _ in range(N):
        line = sys.stdin.readline().strip()
        graph.append(line)

    # Initialize answer matrix with -1
    answer = [[-1 for _ in range(N)] for _ in range(N)]

    # For each pair (i, j), perform BFS to find the shortest path
    for i in range(N):
        for j in range(N):
            # If i == j, the answer is 0
            if i == j:
                answer[i][j] = 0
                continue

            # BFS queue: (current node, current string, depth)
            queue = deque()

            # For each possible edge from i, add to queue
            for k in range(N):
                if graph[i][k] != '-':
                    queue.append( (k, graph[i][k], 1) )

            # BFS to find the shortest palindrome path
            while queue:
                node, s, depth = queue.popleft()

                # If we reached j, check if the string is a palindrome
                if node == j:
                    if s == s[::-1]:
                        if answer[i][j] == -1 or depth < answer[i][j]:
                            answer[i][j] = depth
                        break
                    else:
                        continue

                # For each possible edge from the current node, add to queue
                for k in range(N):
                    if graph[node][k] != '-':
                        new_s = s + graph[node][k]
                        if new_s == new_s[::-1]:
                            if answer[i][j] == -1 or depth + 1 < answer[i][j]:
                                answer[i][j] = depth + 1
                                queue.append( (k, new_s, depth + 1) )

    # Print the answer matrix
    for row in answer:
        print(' '.join(map(str, row)))

if __name__ == '__main__':
    solve()

