import sys
import threading
from collections import deque

MOD = 998244353

def main():
    import sys
    input = sys.stdin.read
    N, S = input().split()
    N = int(N)

    # Precompute valid parentheses pairs
    stack = []
    pairs = [0] * N
    for i in range(N):
        if S[i] == '(':
            stack.append(i)
        else:
            if stack:
                j = stack.pop()
                pairs[j] = i
                pairs[i] = j

    # Dynamic programming
    dp = [set() for _ in range(N)]
    for i in range(N):
        if S[i] == '(': 
            dp[i].add(i)
        else:
            dp[i].add(i)

    # For each position, try to flip a valid substring
    for l in range(N):
        for r in range(l, N):
            # Check if substring is valid
            if pairs[l] == r:
                # Flip this substring
                for i in range(l, r+1):
                    if S[i] == '(': 
                        dp[i].add(r - (i - l))
                    else:
                        dp[i].add(r - (i - l))

    # Count unique strings
    result = 1
    for i in range(N):
        result = (result * len(dp[i])) % MOD

    print(result)

if __name__ == "__main__":
    main()

