def shortest_palindrome(S):
    # Find the longest prefix that is a palindrome
    i = 0
    j = len(S) - 1
    while i < j:
        if S[i] == S[j]:
            i += 1
            j -= 1
        else:
            break
    # If the entire string is a palindrome, return it
    if i >= j:
        return S
    # Otherwise, add the reverse of the suffix to the beginning
    return S + S[:i][::-1]

